package com.centrepay.mobile;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.Editable;
import android.text.InputType;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.FrameLayout;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import java.util.List;

public class TariffActivity extends Activity {
    private static final int BROWN=Palette.PRIMARY_DARK, TERRACOTTA=Palette.PRIMARY, CREAM=Palette.BACKGROUND, SURFACE=Palette.SURFACE, TEXT=Palette.TEXT, MUTED=Palette.MUTED, BORDER=Palette.BORDER;
    private StudentDatabaseHelper database; private String level="1AC"; private TextView b1,b2,b3,b4,annualPreview,totalSummary,saveButton; private CheckBox math,french,pc,svt; private EditText total,duration,mathAmount,frenchAmount,pcAmount,svtAmount,centerAmount; private LinearLayout tariffList; private long editingId=-1;
    @Override public void onCreate(Bundle state) {
        super.onCreate(state); getWindow().setStatusBarColor(BROWN); database=new StudentDatabaseHelper(this);
        LinearLayout root=column(); root.setBackgroundColor(CREAM); root.addView(hero(),new LinearLayout.LayoutParams(MATCH,dp(88)));
        ScrollView scroll=new ScrollView(this); LinearLayout content=column(); content.setPadding(dp(12),dp(12),dp(12),dp(30));
        LinearLayout form=section(R.drawable.ic_sell_24,"Nouveau tarif","Définir le niveau, les matières et les montants");
        form.addView(label("Niveau scolaire"),margins(MATCH,WRAP,0,dp(14),0,dp(8))); LinearLayout levels=row(); b1=levelChip("1AC"); b2=levelChip("2AC"); b3=levelChip("3AC"); b4=levelChip("TC"); levels.addView(b1,margins(0,dp(44),0,0,dp(5),0,1)); levels.addView(b2,margins(0,dp(44),dp(5),0,dp(5),0,1)); levels.addView(b3,margins(0,dp(44),dp(5),0,dp(5),0,1));levels.addView(b4,margins(0,dp(44),dp(5),0,0,0,1)); form.addView(levels); selectLevel("1AC");
        form.addView(label("Matières concernées"),margins(MATCH,WRAP,0,dp(16),0,dp(8))); LinearLayout packs=row(); math=chip("Math"); french=chip("Français"); pc=chip("PC"); svt=chip("SVT"); packs.addView(math,margins(0,dp(46),0,0,dp(5),0,1)); packs.addView(french,margins(0,dp(46),dp(5),0,dp(5),0,1)); packs.addView(pc,margins(0,dp(46),dp(5),0,dp(5),0,1)); packs.addView(svt,margins(0,dp(46),dp(5),0,0,0,1)); form.addView(packs);
        total=input("Calcul automatique"); total.setEnabled(false); total.setAlpha(1f); duration=input("10"); duration.setText("10"); LinearLayout priceRow=row(); addSmallField(priceRow,"Tarif mensuel",total); addSmallField(priceRow,"Durée (mois)",duration); form.addView(priceRow,margins(MATCH,WRAP,0,dp(14),0,0)); content.addView(form);
        mathAmount=input("50 DH"); frenchAmount=input("40 DH"); pcAmount=input("40 DH"); svtAmount=input("30 DH"); centerAmount=input("40 DH");
        LinearLayout distribution=section(R.drawable.ic_analytics_24,"Répartition du montant","Répartir le tarif mensuel par matière"); LinearLayout grid1=row(); addSmallField(grid1,"Math",mathAmount); addSmallField(grid1,"Français",frenchAmount); distribution.addView(grid1,margins(MATCH,WRAP,0,dp(14),0,0)); LinearLayout grid2=row(); addSmallField(grid2,"PC",pcAmount); addSmallField(grid2,"SVT",svtAmount); addSmallField(grid2,"Centre",centerAmount); distribution.addView(grid2);totalSummary=text("Total mensuel  0 DH",18,BROWN,true);totalSummary.setGravity(Gravity.CENTER_VERTICAL);totalSummary.setPadding(dp(14),0,dp(14),0);totalSummary.setBackground(round(0xffe6f7f4,dp(12),Color.TRANSPARENT,0));distribution.addView(totalSummary,margins(MATCH,dp(58),0,dp(12),0,0)); content.addView(distribution,margins(MATCH,WRAP,0,dp(12),0,0));
        LinearLayout annual=section(R.drawable.ic_calendar_month_24,"Aperçu annuel","Estimation selon la durée choisie");annualPreview=text("0 DH",20,BROWN,true);annualPreview.setGravity(Gravity.END);annual.addView(annualPreview,margins(MATCH,WRAP,0,dp(10),0,0));content.addView(annual,margins(MATCH,WRAP,0,dp(12),0,0));
        LinearLayout existing=section(R.drawable.ic_description_24,"Tarifs existants","Formules déjà créées pour le niveau choisi");tariffList=column();existing.addView(tariffList,margins(MATCH,WRAP,0,dp(12),0,0));content.addView(existing);
        LinearLayout actions=row();TextView reset=text("↻  Réinitialiser",15,BROWN,true);reset.setGravity(Gravity.CENTER);reset.setBackground(round(Color.TRANSPARENT,dp(12),BROWN,dp(1)));reset.setOnClickListener(v->resetForm());actions.addView(reset,margins(0,dp(54),0,0,dp(6),0,1));saveButton=text("▣  Enregistrer le tarif",15,Color.WHITE,true);saveButton.setGravity(Gravity.CENTER);saveButton.setBackground(gradient(BROWN,TERRACOTTA,dp(12)));saveButton.setOnClickListener(v->saveTariff());actions.addView(saveButton,margins(0,dp(54),dp(6),0,0,0,1));content.addView(actions,margins(MATCH,WRAP,0,dp(14),0,0));
        scroll.addView(content,new ScrollView.LayoutParams(MATCH,WRAP)); root.addView(scroll,new LinearLayout.LayoutParams(MATCH,0,1f)); setContentView(root);
        View.OnClickListener listener=v->updateInputs(); math.setOnClickListener(listener); french.setOnClickListener(listener); pc.setOnClickListener(listener); svt.setOnClickListener(listener);
        TextWatcher calculator=new TextWatcher(){@Override public void beforeTextChanged(CharSequence s,int a,int b,int c){} @Override public void onTextChanged(CharSequence s,int a,int b,int c){updateTotal();} @Override public void afterTextChanged(Editable s){}};
        mathAmount.addTextChangedListener(calculator); frenchAmount.addTextChangedListener(calculator); pcAmount.addTextChangedListener(calculator); svtAmount.addTextChangedListener(calculator); centerAmount.addTextChangedListener(calculator); duration.addTextChangedListener(calculator);
        updateInputs(); renderTariffs();
    }
    private View hero(){FrameLayout hero=new FrameLayout(this);hero.setBackground(gradient(TERRACOTTA,0xff14b8a6,0));LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),0,dp(16),0);ImageView back=icon(R.drawable.ic_arrow_back_24,Color.WHITE);back.setPadding(dp(4),dp(4),dp(4),dp(4));back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout titles=column();titles.addView(text("Gestion des tarifs",20,Color.WHITE,true));titles.addView(text("Créer et modifier les formules",12,0xffd7efed,false),margins(MATCH,WRAP,0,dp(3),0,0));bar.addView(titles,margins(0,WRAP,dp(12),0,0,0,1));bar.addView(text("CentrePay",18,Color.WHITE,true));hero.addView(bar,new FrameLayout.LayoutParams(MATCH,MATCH));return hero;}
    private void selectLevel(String selected){level=selected; setLevelStyle(b1,"1AC".equals(level));setLevelStyle(b2,"2AC".equals(level));setLevelStyle(b3,"3AC".equals(level));setLevelStyle(b4,"TC".equals(level));if(tariffList!=null)renderTariffs();}
    private TextView levelChip(String value){TextView b=text(value,16,MUTED,true);b.setGravity(Gravity.CENTER);b.setPadding(dp(18),0,dp(18),0);b.setOnClickListener(v->selectLevel(value));return b;}
    private void setLevelStyle(TextView view,boolean selected){view.setTextColor(selected?Color.WHITE:TEXT);view.setBackground(round(selected?BROWN:0xffeff3f7,dp(12),Color.TRANSPARENT,0));}
    private CheckBox chip(String value){CheckBox b=new CheckBox(this);b.setText(value);b.setTextSize(13);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);int color="Math".equals(value)?0xff10b981:"Français".equals(value)?0xff3b82f6:"PC".equals(value)?0xff8b5cf6:0xfff97316;int bg="Math".equals(value)?0xffecfdf5:"Français".equals(value)?0xffeff6ff:"PC".equals(value)?0xfff3e8ff:0xfffff7ed;b.setTextColor(color);b.setGravity(Gravity.CENTER);b.setPadding(dp(3),0,dp(5),0);b.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{color,MUTED}));b.setBackground(round(bg,dp(12),Color.TRANSPARENT,0));return b;}
    private void addSmallField(LinearLayout row,String title,EditText field){LinearLayout box=column();box.addView(label(title),margins(MATCH,WRAP,0,0,0,dp(6)));box.addView(field,new LinearLayout.LayoutParams(MATCH,dp(54)));row.addView(box,margins(0,WRAP,0,0,dp(10),0,1));}
    private void updateInputs(){enable(mathAmount,math.isChecked());enable(frenchAmount,french.isChecked());enable(pcAmount,pc.isChecked());enable(svtAmount,svt.isChecked());updateTotal();}
    private void enable(EditText e,boolean on){e.setEnabled(on);e.setAlpha(on?1:.45f);if(!on)e.setText("0");else if("0".contentEquals(e.getText()))e.setText("");}
    private void updateTotal(){if(total==null)return;int sum=number(mathAmount)+number(frenchAmount)+number(pcAmount)+number(svtAmount)+number(centerAmount);total.setText(sum>0?sum+" DH":"");if(totalSummary!=null)totalSummary.setText("Total mensuel        "+sum+" DH");if(annualPreview!=null)annualPreview.setText((sum*Math.max(0,number(duration)))+" DH");}
    private void resetForm(){editingId=-1;math.setChecked(false);french.setChecked(false);pc.setChecked(false);svt.setChecked(false);mathAmount.setText("0");frenchAmount.setText("0");pcAmount.setText("0");svtAmount.setText("0");centerAmount.setText("");duration.setText("10");selectLevel("1AC");updateInputs();if(saveButton!=null)saveButton.setText("▣  Enregistrer le tarif");}
    private int number(EditText input){try{return Integer.parseInt(input.getText().toString().replace("DH","").trim());}catch(Exception ignored){return 0;}}
    private void saveTariff(){if(number(duration)<=0){duration.setError("Durée invalide");return;}duration.setError(null);String key=TariffOption.packKey(math.isChecked(),french.isChecked(),pc.isChecked(),svt.isChecked());if(key.isEmpty()){say("Choisissez au moins une matière.");return;}Integer m=subject(mathAmount,math.isChecked(),"Math"),f=subject(frenchAmount,french.isChecked(),"Français"),p=subject(pcAmount,pc.isChecked(),"PC"),s=subject(svtAmount,svt.isChecked(),"SVT"),c=amount(centerAmount,"la part du centre");if(m==null||f==null||p==null||s==null||c==null)return;int t=m+f+p+s+c;if(t<=0){say("Saisissez au moins une part.");return;}if(database.tariffOptionExists(level,key,editingId)){say("Une formule avec ces matières existe déjà pour "+level+".");return;}if(editingId<0){long id=database.addTariffOption(level,key,t,m,f,p,s,c);if(id<0){say("Impossible d'enregistrer ce tarif.");return;}database.autoAssignUniqueTeachers(id);say("Tarif ajouté.");}else{if(!database.updateTariffOption(editingId,level,key,t,m,f,p,s,c)){say("Impossible de modifier ce tarif.");return;}database.autoAssignUniqueTeachers(editingId);say("Tarif modifié.");}resetForm();renderTariffs();}
    private Integer amount(EditText e,String name){try{int v=Integer.parseInt(e.getText().toString().replace("DH","").trim());if(v<=0)throw new Exception();e.setError(null);return v;}catch(Exception x){e.setError("Montant requis");say("Saisissez un montant valide pour "+name+".");return null;}}
    private Integer subject(EditText e,boolean chosen,String name){return chosen?amount(e,name):0;}
    private void renderTariffs(){tariffList.removeAllViews();List<TariffOption> list=database.getTariffOptions(level);if(list.isEmpty()){TextView empty=text("Aucun tarif enregistré pour "+level+".",15,MUTED,false);empty.setGravity(Gravity.CENTER);empty.setPadding(0,dp(28),0,dp(28));empty.setBackground(round(SURFACE,dp(20),BORDER,dp(1)));tariffList.addView(empty);return;}for(TariffOption o:list)tariffList.addView(card(o),margins(MATCH,WRAP,0,0,0,dp(12)));}
    private View card(TariffOption o){LinearLayout card=column();card.setPadding(dp(16),dp(16),dp(16),dp(14));card.setElevation(dp(3));card.setBackground(round(SURFACE,dp(20),Color.TRANSPARENT,0));LinearLayout top=row();top.setGravity(Gravity.CENTER_VERTICAL);top.addView(text(o.studentAmount+" DH / mois",20,TEXT,true),new LinearLayout.LayoutParams(0,WRAP,1));TextView pack=text(TariffOption.packLabel(o.packKey),13,TERRACOTTA,true);pack.setPadding(dp(9),dp(5),dp(9),dp(5));pack.setBackground(round(Color.rgb(231,247,244),dp(12),Color.TRANSPARENT,0));top.addView(pack);TextView menu=text("⋮",24,MUTED,true);menu.setGravity(Gravity.CENTER);menu.setOnClickListener(v->showTariffActions(o));top.addView(menu,new LinearLayout.LayoutParams(dp(40),dp(40)));card.addView(top);card.addView(text(distributionText(o),13,MUTED,false),margins(MATCH,WRAP,0,dp(8),0,0));LinearLayout foot=row();foot.setGravity(Gravity.CENTER_VERTICAL);foot.addView(text("Estimation 10 mois :  "+(o.studentAmount*10)+" DH",12,TEXT,true),new LinearLayout.LayoutParams(0,WRAP,1));TextView teachers=text("Affecter les profs  ›",13,TERRACOTTA,true);teachers.setPadding(dp(10),dp(8),dp(10),dp(8));teachers.setBackground(round(Palette.PRIMARY_SOFT,dp(14),0,0));teachers.setOnClickListener(v->openAssignments(o));foot.addView(teachers);card.addView(foot,margins(MATCH,WRAP,0,dp(12),0,0));return card;}
    private String distributionText(TariffOption o){StringBuilder s=new StringBuilder();appendPart(s,"Math",o.mathAmount);appendPart(s,"Français",o.frenchAmount);appendPart(s,"PC",o.pcAmount);appendPart(s,"SVT",o.svtAmount);appendPart(s,"Centre",o.centerAmount);return s.toString();}
    private void appendPart(StringBuilder value,String label,int amount){if(amount<=0)return;if(value.length()>0)value.append("  ·  ");value.append(label).append(" ").append(amount).append(" DH");}
    private void openAssignments(TariffOption o){Intent i=new Intent(this,TariffTeacherAssignmentActivity.class);i.putExtra(TariffTeacherAssignmentActivity.EXTRA_TARIFF_ID,o.id);startActivity(i);}
    private void showTariffActions(TariffOption o){String[] actions={"Modifier le tarif","Affecter les professeurs","Supprimer"};new AlertDialog.Builder(this).setTitle(o.studentAmount+" DH — "+TariffOption.packLabel(o.packKey)).setItems(actions,(dialog,index)->{if(index==0)editTariff(o);else if(index==1)openAssignments(o);else confirmDelete(o);}).show();}
    private void editTariff(TariffOption o){editingId=o.id;selectLevel(o.level);math.setChecked(o.mathAmount>0);french.setChecked(o.frenchAmount>0);pc.setChecked(o.pcAmount>0);svt.setChecked(o.svtAmount>0);mathAmount.setText(String.valueOf(o.mathAmount));frenchAmount.setText(String.valueOf(o.frenchAmount));pcAmount.setText(String.valueOf(o.pcAmount));svtAmount.setText(String.valueOf(o.svtAmount));centerAmount.setText(String.valueOf(o.centerAmount));updateInputs();saveButton.setText("▣  Modifier le tarif");say("Tarif chargé dans le formulaire.");}
    private void confirmDelete(TariffOption o){new AlertDialog.Builder(this).setTitle("Supprimer ce tarif ?").setMessage("La formule "+TariffOption.packLabel(o.packKey)+" de "+o.studentAmount+" DH sera supprimée. Les anciens dossiers d'élèves ne seront pas modifiés.").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(dialog,which)->{if(database.deleteTariffOption(o.id)){if(editingId==o.id)resetForm();renderTariffs();say("Tarif supprimé.");}else say("Suppression impossible.");}).show();}
    @Override protected void onResume(){super.onResume();if(tariffList!=null)renderTariffs();}
    private LinearLayout section(int iconResource,String title,String subtitle){LinearLayout card=column();card.setPadding(dp(12),dp(14),dp(12),dp(14));card.setBackground(round(SURFACE,dp(16),BORDER,dp(1)));card.setElevation(dp(1));LinearLayout head=row();head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout bubble=row();bubble.setGravity(Gravity.CENTER);bubble.setBackground(round(0xffe6f7f4,dp(22),Color.TRANSPARENT,0));bubble.addView(icon(iconResource,BROWN),new LinearLayout.LayoutParams(dp(23),dp(23)));head.addView(bubble,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout copy=column();copy.addView(text(title,16,TEXT,true));copy.addView(text(subtitle,11,MUTED,false),margins(MATCH,WRAP,0,dp(3),0,0));head.addView(copy,margins(0,WRAP,dp(11),0,0,0,1));card.addView(head);return card;}
    private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(Color.rgb(178,165,154));e.setTextColor(TEXT);e.setTextSize(16);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setPadding(dp(14),0,dp(10),0);e.setBackground(round(SURFACE,dp(15),BORDER,dp(1)));return e;}
    private TextView label(String s){return text(s,14,TEXT,true);} private void say(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();} private ImageView icon(int resource,int color){ImageView v=new ImageView(this);v.setImageResource(resource);v.setImageTintList(ColorStateList.valueOf(color));v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);return v;}private TextView text(String s,int z,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);t.setIncludeFontPadding(false);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);return l;}private GradientDrawable round(int c,int r,int stroke,int w){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);if(w>0)d.setStroke(w,stroke);return d;}private GradientDrawable gradient(int a,int b,int r){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{a,b});d.setCornerRadius(r);return d;}private LinearLayout.LayoutParams margins(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(l,t,r,b);return p;}private LinearLayout.LayoutParams margins(int w,int h,int l,int t,int r,int b,float weight){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h,weight);p.setMargins(l,t,r,b);return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static final int MATCH=ViewGroup.LayoutParams.MATCH_PARENT,WRAP=ViewGroup.LayoutParams.WRAP_CONTENT;
}
